BEGIN READ ONLY; SET LOCAL statement_timeout='10s'; SELECT set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',(SELECT auth_user_id::text FROM public.staff WHERE role='owner' AND active AND terminated_at IS NULL AND auth_user_id IS NOT NULL ORDER BY created_at LIMIT 1))::text,true); SET LOCAL ROLE authenticated; SELECT jsonb_build_object('role',current_user,'eligible_shops',(SELECT count(*) FROM public.sync_staff_shop_ids()),'write_caller_role',(SELECT caller_role FROM public.admin_require_write_caller()),'pull_ok',public.sync_pull(0,1,NULL)->'ok','pull_records',jsonb_array_length(public.sync_pull(0,1,NULL)->'records')) AS result; ROLLBACK;
